namespace Fanex.Age.Excel.Reports.Result
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using Fanex.Age.UI.Reports.DTO.Result.Entities;
    using Fanex.Age.Utility.NPOI;
    using NPOI.HSSF.UserModel;
    using NPOI.SS.UserModel;
    using Sunplus.Agent.Model.BL.Cache;

    /// <summary>
    /// TODO: Update summary.
    /// </summary>
    public class ResultVirtualCyclingReport : BaseResultReport, IReportBuilder
    {
        private ResultReportBuilder _builder;

        public ResultVirtualCyclingReport(string filePath, ResultReportBuilder builder)
            : base(filePath)
        {
            _builder = builder;
        }

        public HSSFWorkbook Build()
        {
            var data = (IList<VirtualHorsesRacingEntity>)_builder.Data;
            if (data == null) return null;

            ISheet templateSheet = hssfWorkbook.GetSheet("Template");
            ISheet resultSheet = hssfWorkbook.GetSheet("Result");
            int rowId = 0;
            int colId = 0;

            // title
            WriteTitle(resultSheet, ref rowId, ref colId, _builder);

            // header
            AssignReportHeader(resultSheet, rowId, colId);
            rowId++;

            var eventTimes = data.Select(x => x.EventTime).Distinct();
            int rowIndex = 0;
            foreach (var eventTime in eventTimes)
            {
                var entities = data.Where(x => x.EventTime == eventTime);
                if (entities.Count() > 0) {
                    if (entities.FirstOrDefault().EventStatus.ToLower().Equals("refund"))
                    {
                        AssignRefundRow(templateSheet, resultSheet, ref rowId, colId, ref rowIndex, eventTime);
                        continue;
                    }
                    else
                    {
                        var raceIndex = 0;
                        foreach (var entity in entities)
                        {
                            if (entity.Place == 0)
                            {
                                continue;
                            }

                            CopyTemplateRow(templateSheet, resultSheet, rowId, rowIndex);

                            AssignResultReportDetail(resultSheet, rowId, colId, raceIndex, entity);                     

                            rowId++;
                            raceIndex++;
                        }

                        resultSheet.MergeCells(rowId - raceIndex, colId, rowId - 1, colId);
                        resultSheet.GetCell(rowId - raceIndex, colId).SetCellValue(eventTime);
                        rowIndex++;
                    }
                    
                }
            }

            hssfWorkbook.RemoveSheetAt(hssfWorkbook.GetSheetIndex(templateSheet));

            return hssfWorkbook;
        }

        private static void AssignResultReportDetail(ISheet resultSheet, int rowId, int colId, int raceIndex, VirtualHorsesRacingEntity entity)
        {
            if (raceIndex == 0)
            {

                resultSheet.GetRow(rowId).WriteCells(
                    colId + 1,
                    Common.GetHorseRacingPlaceString(entity.Place),
                    entity.HorseNo.ToString(),
                    CacheRef.GetHorseTeamName(entity.HorseId),
                    entity.WinOdds,
                    entity.PlaceOdds,
                    entity.IsFavor);
            }
            else
            {
                resultSheet.GetRow(rowId).WriteCells(
                colId + 1,
                Common.GetHorseRacingPlaceString(entity.Place),
                entity.HorseNo.ToString(),
                CacheRef.GetHorseTeamName(entity.HorseId),
                string.Empty,
                entity.PlaceOdds,
                entity.IsFavor);
            }
        }

        private static void AssignReportHeader(ISheet resultSheet, int rowId, int colId)
        {
            resultSheet.GetCell(rowId, colId).SetCellValue(Resources.Lang.lblRace);
            resultSheet.GetCell(rowId, colId + 3).SetCellValue(Resources.Lang.result);
            resultSheet.GetCell(rowId, colId + 4).SetCellValue(Resources.Lang.WinHR);
            resultSheet.GetCell(rowId, colId + 5).SetCellValue(Resources.Lang.Place);
            resultSheet.GetCell(rowId, colId + 6).SetCellValue(Resources.Lang.status);
        }

        private static void AssignRefundRow(
            ISheet templateSheet, 
            ISheet resultSheet, 
            ref int rowId, 
            int colId,
            ref int rowIndex, 
            DateTime eventTime)
        {
            CopyTemplateRow(templateSheet, resultSheet, rowId, rowIndex);

            resultSheet.GetRow(rowId).WriteCells(
                colId,
                eventTime,
                "N/A",
                "N/A",
                "N/A",
                "N/A",
                "N/A",
                "Refund");

            rowId++;
            rowIndex++;
        }

        private static void CopyTemplateRow(
            ISheet templateSheet,
            ISheet resultSheet,
            int rowId, int rowIndex)
        {
            if (rowIndex % 2 == 0)
            {
                resultSheet.CopyRow(templateSheet, 1, rowId);
            }
            else
            {
                resultSheet.CopyRow(templateSheet, 3, rowId);
            }
        }
    }
}
